const productsEl=document.getElementById("products");let catalogPage=1;
function renderProducts(){const visibleProducts=products.filter(p=>!p.deletedAt&&p.status!=='hidden').sort((a,b)=>(Number(a.displayOrder)||Number.MAX_SAFE_INTEGER)-(Number(b.displayOrder)||Number.MAX_SAFE_INTEGER)||(Number(a.id)||0)-(Number(b.id)||0));const page=storePageRows(visibleProducts,24,catalogPage,'catalogPagination',productsEl,value=>{catalogPage=value;renderProducts();});catalogPage=page.page;productsEl.innerHTML=page.rows.map(p=>{return `<article class="product ${canBuy(p)?'':'soldout'}"><a class="product-link" href="product.html?id=${p.id}">${productVisual(p)}<span class="badge">${canBuy(p)?'판매 중':'품절'}</span><div class="product-info"><h3>${escapeText(p.name)}</h3><div class="price">${won(p.price)}</div><span class="detail-hint">상품 소개 · 배송 안내 →</span></div></a></article>`;}).join('')||EmptyStates.html('products');updateSelection();};

renderProducts();window.addEventListener("store-data-change",renderProducts);
